inline const Glyph* getGlyph(char c) {
  switch (c) {
    case '0': return &s_glyph_digit_0;
    case '1': return &s_glyph_digit_1;
    case '2': return &s_glyph_digit_2;
    case '3': return &s_glyph_digit_3;
    case '4': return &s_glyph_digit_4;
    case '5': return &s_glyph_digit_5;
    case '6': return &s_glyph_digit_6;
    case '7': return &s_glyph_digit_7;
    case '8': return &s_glyph_digit_8;
    case '9': return &s_glyph_digit_9;
    case ':': return &s_glyph_colon;
    default: return nullptr;
  }
}

inline int getStringWidth(const char* str) {
  int w = 0;
  for (const char* p = str; *p; ++p) {
    if (const auto* g = getGlyph(*p)) {
      w += g->adv;
    }
  }
  return w;
}

inline void drawClock(const GfxRenderer& renderer, int centerX, int baselineY, const char* str) {
  const int totalW = getStringWidth(str);
  int curX = centerX - totalW / 2;
  for (const char* p = str; *p; ++p) {
    const auto* g = getGlyph(*p);
    if (!g) continue;
    int bitIdx = 0;
    const int glyphX = curX + (g->adv - g->w) / 2;
    for (int r = 0; r < g->h; ++r) {
      const int py = baselineY - g->top + r;
      for (int c = 0; c < g->w; ++c, ++bitIdx) {
        if ((g->data[bitIdx >> 3] >> (7 - (bitIdx & 7))) & 1) {
          renderer.drawPixel(glyphX + c, py, true);
        }
      }
    }
    curX += g->adv;
  }
}

